// MeetGeek on the business's own API key: every operation in MeetGeek's public API (docs.meetgeek.ai) — meetings,
// transcripts, summaries, highlights, insights, recordings, uploads and teams — plus sending its notetaker into a
// meeting. actions.json is generated by `bun scripts/openapi-actions.ts meetgeek`. A meeting's analysis finishing comes by
// webhook once its address is pasted into MeetGeek (triggers.ts); new meetings are also polled (polls/meetgeek.ts).
import { z } from "zod";
import { AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, receive, triggers, watch, webhookSetup } from "./triggers";

// API keys belong to a region: the key is pasted as us:<key> for US accounts (us.meetgeek.ai), eu:<key> or bare otherwise
const HOSTS: Record<string, string> = { us: "https://api-us.meetgeek.ai", eu: "https://api-eu.meetgeek.ai" };
export const split = (secret: string) => {
  const m = /^(us|eu):(.+)$/i.exec(secret.trim());
  return m ? { host: HOSTS[m[1]!.toLowerCase()], token: m[2]!.trim() } : { host: undefined, token: secret.trim() };
};

export const api: Api = {
  name: "MeetGeek",
  base: "https://api.meetgeek.ai",
  tokenHelp: "MeetGeek → Integrations → Public API",
  auth: (secret) => ({ Authorization: `Bearer ${split(secret).token}` }),
  url: (secret, base, path) => `${split(secret).host ?? base}${path}`,
};

export const meetgeek: OwnApp = {
  app: "meetgeek",
  name: "MeetGeek",
  logo: "/logos/meetgeek.png",
  keyField: {
    label: "API key",
    help: "In MeetGeek, open Integrations (app.meetgeek.ai/integrations) → Public API, generate the API key and copy it. Any plan has it, but Free and Pro allow 100 calls a day; Business and Enterprise 100 a minute. Account on MeetGeek's US site (us.meetgeek.ai)? Paste it as us:YOUR_KEY.",
    placeholder: "your-api-key",
  },
  async check(secret) {
    if (!split(secret).token) throw new AppsError("paste your MeetGeek API key");
    // MeetGeek has no "who am I" call; listing teams is the cheapest one that needs a working key
    await call(api, secret, { method: "GET", path: "/v1/teams", query: [], headers: [] }, {});
  },
  push: { events, triggers, start: (_key, connection) => watch(connection), receive: (delivery, key) => receive(api, delivery, key) },
  actions: {
    ...(await specActions(new URL("./actions.json", import.meta.url), api)),
    get_webhook_setup: {
      description:
        "Where to paste Emplio's address in MeetGeek so its instant triggers (meeting_analyzed, analysis_failed) work. MeetGeek takes its webhook address only on its Integrations page, so the owner does this once by hand; tell them the address exactly as this answers. The polled new_meeting trigger needs none of this.",
      input: z.object({}),
      readOnly: true,
      run: async (_input: Record<string, unknown>, _key: string, connection?: string) => webhookSetup(connection),
    },
  },
};
